/**
 * Image registry. Photography is generated by scripts/generate-images.mjs into /public/images.
 * Explicit width/height on every usage = zero CLS. Alt text is authored per page in the
 * language modules (content blocks / gallery items).
 */
export interface SiteImage {
  src: string;
  width: number;
  height: number;
}

export const IMAGES: Record<string, SiteImage> = {
  hero: { src: "/images/hot-air-balloon-marrakech-sunrise-atlas.webp", width: 1536, height: 768 },
  atlasAerial: { src: "/images/atlas-mountains-hot-air-balloon-aerial.webp", width: 1536, height: 768 },
  palmgrove: { src: "/images/montgolfiere-marrakech-palmeraie-lever-soleil.webp", width: 1344, height: 768 },
  private: { src: "/images/hot-air-balloon-private-flight-couple-marrakech.webp", width: 1344, height: 768 },
  vip: { src: "/images/hot-air-balloon-vip-flight-champagne-marrakech.webp", width: 1344, height: 768 },
  camel: { src: "/images/hot-air-balloon-camel-ride-combo-marrakech.webp", width: 1344, height: 768 },
  agafay: { src: "/images/hot-air-balloon-agafay-desert-marrakech.webp", width: 1344, height: 768 },
  agadir: { src: "/images/hot-air-balloon-agadir-souss-valley.webp", width: 1344, height: 768 },
  breakfast: { src: "/images/berber-breakfast-hot-air-balloon-marrakech.webp", width: 1344, height: 768 },
  inflation: { src: "/images/hot-air-balloon-inflation-dawn-marrakech.webp", width: 1344, height: 768 },
  certificate: { src: "/images/hot-air-balloon-flight-certificate-landing.webp", width: 1344, height: 768 },
  pilot: { src: "/images/hot-air-balloon-pilot-morocco.webp", width: 864, height: 1152 },
  burner: { src: "/images/hot-air-balloon-burner-flame.webp", width: 1344, height: 768 },
  proposal: { src: "/images/hot-air-balloon-marriage-proposal-marrakech.webp", width: 1344, height: 768 },
  medinaAerial: { src: "/images/marrakech-medina-aerial-sunrise.webp", width: 1344, height: 768 },
  passengers: { src: "/images/hot-air-balloon-passengers-basket.webp", width: 1344, height: 768 },
};

export function image(key: string): SiteImage {
  return IMAGES[key] || IMAGES.hero;
}
